(() => {
 const $=id=>document.getElementById(id),L=window.SC_LESSONS;let active=0,state={},seed=42,lastResult;
 const fmt=(v,u)=>u==='$'?SC.money(v):u==='%'?v+'%':u==='years'?v+' yr':u==='pow2'?2**v:SC.round(v,Number.isInteger(v)?0:2);
 function chart(r){const width=Math.max(340,Math.min(760,$('chart').clientWidth||760)),right=width-25;$('chart').setAttribute('viewBox',`0 0 ${width} 325`);let xmin=r.x?.[0]??0,xmax=r.x?.[1]??1;const ys=r.series.flatMap(s=>s.data.map(p=>p[1]));let lo=Math.min(0,...ys),hi=Math.max(0,...ys);const pad=Math.max((hi-lo)*.12,.1);let ymin=r.y?.[0]??(lo-pad),ymax=r.y?.[1]??(hi+pad);const X=x=>65+(x-xmin)/(xmax-xmin)*(right-65),Y=y=>265-(y-ymin)/(ymax-ymin)*230;let h='<title>'+L[active].chart+'</title>';for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4,x=xmin+(xmax-xmin)*i/4;h+=`<line x1="65" x2="${right}" y1="${Y(y)}" y2="${Y(y)}" stroke="#e4ece7" stroke-dasharray="3 5"/><text x="55" y="${Y(y)+4}" text-anchor="end">${r.yf?r.yf(y):SC.round(y,1)}</text>`;if(!r.series[0].bars)h+=`<text x="${X(x)}" y="286" text-anchor="middle">${r.xf?r.xf(x):SC.round(x,1)}</text>`}if(ymin<0&&ymax>0)h+=`<line x1="65" x2="${right}" y1="${Y(0)}" y2="${Y(0)}" stroke="#aebfb7"/>`;
 r.series.forEach(s=>{if(s.bars){const w=Math.min(44,(right-65)/s.data.length*.65);s.data.forEach(([x,y])=>{h+=`<rect x="${X(x)-w/2}" y="${Y(y)}" width="${w}" height="${Math.max(0,Y(0)-Y(y))}" rx="3" fill="${s.color}"/><text x="${X(x)}" y="286" text-anchor="middle">${x}</text>`})}else{const d=s.data.map(([x,y],i)=>`${i?'L':'M'}${X(x).toFixed(2)},${Y(y).toFixed(2)}`).join(' ');h+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="${s.width||2.5}" ${s.dash?'stroke-dasharray="6 5"':''}/>`}});
 if(r.marker){const [x,y]=r.marker;h+=`<circle cx="${X(x)}" cy="${Y(y)}" r="6" fill="#173d34" stroke="white" stroke-width="2"/>`}h+=`<text x="${width/2}" y="315" text-anchor="middle">${r.xlabel||'Time'}</text>`;$('chart').innerHTML=h;$('chart').setAttribute('aria-label',`${L[active].chart}. ${r.explanation}`);$('legend').innerHTML=r.series.filter(s=>!s.hideLegend).map(s=>`<span style="--c:${s.color}">${s.name}</span>`).join('');
 }
 function update(){lastResult=L[active].compute(state,seed);const r=lastResult;$('stats').innerHTML=r.stats.map(([label,value])=>`<div class="stat"><label>${label}</label><strong>${value}</strong></div>`).join('');chart(r);$('explanation').textContent=r.explanation;$('chart-note').textContent=r.note||'';}
 function render(){const l=L[active];window.renderLearning(l.id);let group='';$('lessons').innerHTML=L.map((x,i)=>{let heading=x.stage!==group?`<div class="nav-group">${x.stage}</div>`:'';group=x.stage;return heading+`<button class="${i===active?'active':''}" ${i===active?'aria-current="step"':''} data-lesson="${i}"><b>${i+1}</b><span>${x.name}</span></button>`}).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>select(+b.dataset.lesson));$('level').textContent=l.stage.toUpperCase();$('title').textContent=l.title;$('intro').textContent=l.intro;$('count').textContent=`${active+1} / ${L.length} APPLETS`;$('chart-title').textContent=l.chart;$('simple-title').textContent=l.simpleTitle;$('simple').textContent=l.simple;$('formula').textContent=l.formula;$('formula-key').textContent=l.key;$('challenge').textContent=l.challenge;$('reading').textContent=l.reading;$('inputs').innerHTML=l.inputs.map(([id,label,min,max,step,d,u])=>`<div class="input"><div class="input-top"><label for="${id}">${label}</label><output class="value" id="value-${id}" for="${id}">${fmt(state[id],u)}</output></div><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${state[id]}" aria-valuetext="${fmt(state[id],u)}"><div class="bounds"><span>${fmt(min,u)}</span><span>${fmt(max,u)}</span></div></div>`).join('');l.inputs.forEach(([id,,,,,u])=>$(id).oninput=e=>{state[id]=+e.target.value;$('value-'+id).textContent=fmt(state[id],u);e.target.setAttribute('aria-valuetext',fmt(state[id],u));update()});$('resample').hidden=!l.random;$('next').innerHTML=active===L.length-1?'Return to probability ↺':'Next concept →';update();}
 function select(i,hash=true){active=i;state=Object.fromEntries(L[i].inputs.map(x=>[x[0],x[5]]));seed=42;render();if(hash)history.replaceState(null,'','#'+L[i].id)}
 $('reset').onclick=()=>select(active);$('resample').onclick=()=>{seed++;update()};$('next').onclick=()=>select((active+1)%L.length);const i=L.findIndex(l=>l.id===location.hash.slice(1));select(i<0?0:i,false);window.addEventListener('resize',()=>chart(lastResult));window.addEventListener('hashchange',()=>{const i=L.findIndex(l=>l.id===location.hash.slice(1));if(i>=0)select(i,false)});
 if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_stochastic_applet',description:'Select a stochastic calculus applet and configure its visible slider inputs.',inputSchema:{type:'object',properties:{lesson:{type:'string',enum:L.map(l=>l.id)},values:{type:'object',additionalProperties:{type:'number'}}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const index=L.findIndex(l=>l.id===input.lesson);if(index<0)throw Error('Unknown lesson');for(const [key,v]of Object.entries(input.values||{})){const d=L[index].inputs.find(x=>x[0]===key);if(!d||!Number.isFinite(v)||v<d[2]||v>d[3]||Math.abs((v-d[2])/d[4]-Math.round((v-d[2])/d[4]))>1e-6)throw Error('Invalid slider value: '+key)}select(index);Object.assign(state,input.values||{});render();return{lesson:L[active].id,values:{...state},results:lastResult.stats,explanation:lastResult.explanation}}})).catch(()=>{})}catch{}}
})();
